"""Differential replay with mostly-valid, state-tracking random workloads."""
import sys, random, struct
sys.path.insert(0, '/workspace/tests')
sys.path.insert(0, '/workspace/project')
from ref import Ref
from ebpf.helper import Agent

DENY = 4294967295
POLICIES = ['match(A,B) allow;', 'startswith(A) allow;', 'contains(B) allow;',
            'endswith(C) allow;', 'match(A,B,C) allow; match(C) allow;',
            'not(contains(A)) allow;', 'match(A) allow; contains(A,A) drop;']


class Gen(object):
    """Generates a realistic mixed workload against a live model."""

    def __init__(self, rng, services, limits):
        self.rng = rng
        self.names = [s['name'] for s in services]
        self.limits = limits
        self.units = []        # [(ns,pid,gen,service)]
        self.gmark = {}
        self.rids = 1
        self.conns = []        # [(id,gen,mark)]
        self.cmark = {}
        self.stream = 0
        self.packets = []      # [(id,gen,stream,dest,delivered)]
        self.files = []        # [(id,gen)]
        self.fmark = {}
        self.epochs = []
        self.stage_mark = 0

    def unit(self):
        rng = self.rng
        if self.units and rng.random() < 0.8:
            return list(rng.choice(self.units)[:3]), rng.choice(self.names)
        ns = rng.randint(0, 2)
        pid = rng.randint(1, 20)
        gen = self.gmark.get((ns, pid), 0) + rng.randint(1, 2)
        svc = rng.choice(self.names)
        self.gmark[(ns, pid)] = gen
        self.units.append((ns, pid, gen, svc))
        return [ns, pid, gen], svc

    def conn(self):
        rng = self.rng
        if self.conns and rng.random() < 0.8:
            return list(rng.choice(self.conns)[:2])
        cid = rng.randint(1, 6)
        gen = self.cmark.get(cid, 0) + 1
        self.cmark[cid] = gen
        self.conns.append((cid, gen, 0))
        return [cid, gen]

    def file(self):
        rng = self.rng
        if self.files and rng.random() < 0.7:
            return list(rng.choice(self.files))
        fid = rng.randint(1, 6)
        gen = self.fmark.get(fid, 0) + 1
        self.fmark[fid] = gen
        self.files.append((fid, gen))
        return [fid, gen]

    def next_stream(self, conn):
        for c in self.conns:
            if c[0] == conn[0] and c[1] == conn[1]:
                c = list(c)
                s = c[2] + 1
                self.conns[self.conns.index(tuple(c))] = tuple([c[0], c[1], s])
                return s
        return 1

    def event(self):
        rng = self.rng
        r = rng.random()
        if r < 0.06 and len(self.epochs) < 6:
            ep = self.stage_mark + rng.randint(1, 3)
            self.epochs.append(ep)
            self.stage_mark = ep
            return {'op': 'stage', 'epoch': ep, 'policy': rng.choice(POLICIES)}
        if r < 0.12 and self.epochs:
            return {'op': 'commit', 'epoch': rng.choice(self.epochs)}
        if r < 0.15 and len(self.epochs) > 1:
            ep = rng.choice(self.epochs[:-1])
            return {'op': 'retire', 'epoch': ep}
        if r < 0.25:
            u, svc = self.unit()
            return {'op': 'spawn', 'unit': u, 'service': svc}
        if r < 0.32 and self.units:
            parent = list(rng.choice(self.units)[:3])
            child, _ = self.unit()
            return {'op': 'clone', 'parent': parent, 'child': child}
        if r < 0.38 and self.units:
            return {'op': 'exit', 'unit': list(rng.choice(self.units)[:3])}
        if r < 0.50 and self.units:
            u, _ = self.unit()
            self.rids += 1
            return {'op': 'begin', 'unit': u, 'rid': self.rids}
        if r < 0.58 and self.units:
            u, _ = self.unit()
            return {'op': 'finish', 'unit': u, 'rid': max(1, self.rids - rng.randint(0, 3))}
        if r < 0.64:
            return {'op': 'open', 'connection': self.conn()}
        if r < 0.76 and self.units:
            u, _ = self.unit()
            c = self.conn()
            s = self.next_stream(c)
            return {'op': 'send', 'unit': u, 'rid': max(1, self.rids - rng.randint(0, 2)),
                    'connection': c, 'stream': s, 'destination': rng.choice(self.names)}
        if r < 0.86 and self.units:
            u, _ = self.unit()
            c = self.conn()
            s = rng.randint(1, 5)
            self.rids += 1
            return {'op': 'recv', 'connection': c, 'stream': s, 'unit': u,
                    'rid': self.rids, 'wire': None}
        if r < 0.90:
            if self.conns:
                c = rng.choice(self.conns)
                return {'op': 'close', 'connection': [c[0], c[1]]}
            return {'op': 'inspect'}
        if r < 0.95 and self.units:
            u, _ = self.unit()
            f = self.file()
            return {'op': 'store', 'unit': u, 'rid': max(1, self.rids - rng.randint(0, 2)), 'file': f}
        if r < 0.98 and self.units:
            u, _ = self.unit()
            f = self.file()
            self.rids += 1
            return {'op': 'load', 'file': f, 'unit': u, 'rid': self.rids}
        if self.files:
            f = rng.choice(self.files)
            return {'op': 'unlink', 'file': [f[0], f[1]]}
        return {'op': 'inspect'}


LIMITS = {'images': 5, 'cells': 60, 'units': 8, 'contexts': 30,
          'connections': 5, 'packets': 10, 'files': 5}


def main():
    bad = 0
    for seed in range(15):
        rng = random.Random(seed)
        services = [{'name': n, 'label': l} for n, l in [('A', 5), ('B', 2), ('C', 9)]]
        gen = Gen(rng, services, LIMITS)
        events = [gen.event() for _ in range(600)]
        ref = Ref(services, LIMITS)
        agent = Agent(services, LIMITS, {})
        handlers = Agent.HANDLERS
        for i, e in enumerate(events):
            want = ref.event(e)
            got = handlers[e['op']](agent, e)
            if got != want:
                bad += 1
                print('seed %d event %d %s\n  got  %s\n  want %s' % (seed, i, e, got, want))
                if bad > 4:
                    return
                break
    print('smart differential: %d mismatches' % bad)


main()
PYEOF
